/**
 * Tour 03 — AI Threat Suggestion (STRIDE)
 *
 * Uses the Online Checkout model built in Tour 02 and runs the full STRIDE
 * analysis against it using the real async BullMQ pipeline — exactly as an
 * end user would. Clicks Analyze, waits for the background job to complete
 * (~60–120s), then captures the populated threat cards and expands one.
 *
 * The threats are generated by qwen/qwen3-coder-next via LM Studio on the
 * local M5 Max. Everything runs through the real product code path: UI →
 * async POST → BullMQ job → AI provider → persist result → poll → render.
 *
 * Depends on: Tour 02 having been run first (creates "Online Checkout" model).
 *
 * Run: TOUR_BASE_URL=https://threatforge.bpmforge.com npx playwright test \
 *      --project=product-tour 03-ai-threat-suggestion.spec.ts
 */
import { test, type Page } from "@playwright/test";
import { TourRecorder, TOUR_VIEWPORT } from "./_recorder";

import { WRITER_EMAIL, WRITER_PASSWORD, writerSkipReason } from "../accounts";

// Tours create and edit models; the demo login is read-only on prod.
test.skip(!!writerSkipReason(), writerSkipReason() ?? "");
const MODEL_NAME_SUBSTRING = "Online Checkout";

async function loginAndFindModelId(page: Page): Promise<string> {
  await page.goto("/login");
  await page.waitForSelector('input[type="email"]');
  await page.fill('input[type="email"]', WRITER_EMAIL);
  await page.fill('input[type="password"]', WRITER_PASSWORD);
  await page.click('button[type="submit"]');
  await page.waitForURL("**/dashboard**", { timeout: 15000 });
  await page.waitForLoadState("networkidle");

  const modelId = await page.evaluate(async (name) => {
    const res = await fetch("/api/threat-models", { credentials: "include" });
    const body = (await res.json()) as {
      data: Array<{ id: string; name: string }>;
    };
    return body.data.find((m) => m.name.includes(name))?.id || null;
  }, MODEL_NAME_SUBSTRING);

  if (!modelId) {
    throw new Error(
      `Tour 03 requires Tour 02 to be run first — "${MODEL_NAME_SUBSTRING}" model not found`,
    );
  }
  return modelId;
}

test.describe("Tour 03 — AI Threat Suggestion", () => {
  test.use({ viewport: TOUR_VIEWPORT });

  test("records tour", async ({ page }) => {
    test.setTimeout(600_000); // 10 min — real async pipeline can take 2–3 min

    const tour = new TourRecorder({
      slug: "03-ai-threat-suggestion",
      title: "Tour 3 — AI Threat Suggestion",
      subtitle:
        "Let the AI analyze the Online Checkout architecture and generate STRIDE threats — specific to this design, not boilerplate.",
      audience:
        "Security architects and technical stakeholders. Shows the real output quality of the AI pipeline running on qwen3-coder-next via LM Studio.",
    });

    // ── Setup: login, find model ────────────────────────────────────────────
    const modelId = await loginAndFindModelId(page);

    // Navigate to the model canvas
    await page.goto(`/models/${modelId}`);
    await page.waitForSelector('[data-testid="rf__wrapper"]', {
      state: "visible",
    });
    await page.waitForLoadState("networkidle");
    await page.waitForTimeout(1500);

    // ── Step 1: Model loaded from Tour 02 ────────────────────────────────────
    await tour.step(page, {
      caption:
        "We reopen the **Online Checkout** model we built in Tour 2. All five components, four data flows, and the trust boundary are stored with their metadata — protocols, authentication, trust levels, data classifications. That metadata becomes the context the AI analyzes.",
      settleMs: 800,
    });

    // ── Step 2: Open the AI tab ──────────────────────────────────────────────
    await tour.step(page, {
      caption:
        "Click the **AI** tab in the right panel. ThreatForge has a dedicated AI surface distinct from the manual threat library — this is where the LLM-driven analysis lives.",
      action: async () => {
        await page.getByRole("tab", { name: /^AI$/i }).first().click();
        await page.waitForTimeout(800);
      },
      highlight: 'button[role="tab"]:has-text("AI")',
      settleMs: 400,
    });

    // ── Step 3: Methodology selector ─────────────────────────────────────────
    await tour.step(page, {
      caption:
        "The **methodology selector** lets you choose STRIDE, PASTA, Kill Chain, or MITRE ATT&CK. Each methodology produces a different view of the same architecture — STRIDE focuses on per-component security properties, PASTA is risk-centric, Kill Chain traces attack lifecycle stages, and MITRE ATT&CK maps to the industry-standard 11 tactics. Re-running with a different methodology surfaces complementary threats.",
      highlight: '[role="combobox"]',
      settleMs: 400,
    });

    // ── Step 4: The Analyze button ───────────────────────────────────────────
    await tour.step(page, {
      caption:
        "Click **Analyze with STRIDE** to kick off the analysis. ThreatForge sends the architecture — components, trust boundaries, data flows, protocols — to the configured AI provider. For this demo we're routing through **LM Studio** on a local M5 Max running `qwen/qwen3-coder-next`, which benchmarked as the best model for schema compliance and output depth across the five we tested.",
      highlight: 'button:has-text("Analyze with STRIDE")',
      settleMs: 400,
    });

    // ── Step 5: Run the analysis (real async pipeline) ───────────────────────
    await tour.step(page, {
      caption:
        "The analysis runs as a real background job through the BullMQ pipeline. On a five-component system it typically takes **60–120 seconds** — the LLM generates detailed attack vectors and mitigations for each component. The UI stays responsive; you can navigate away, edit the canvas, or start a second model while the background job runs. For more complex systems ThreatForge splits the analysis across multiple parallel passes (per-component + cross-component).",
      action: async () => {
        await page
          .getByRole("button", { name: /analyze with stride/i })
          .click();
        // Wait for the background job toast to appear
        await page.waitForTimeout(2000);
      },
      settleMs: 800,
    });

    // ── Step 6: Wait for results ─────────────────────────────────────────────
    console.log("  Waiting for real AI analysis to complete (~60-120s)...");
    // Poll for threat cards to appear — the UI auto-updates when the job completes
    const threatCardSelector =
      '[data-testid="ai-threat-card"], [class*="threat-card"], [class*="ThreatCard"]';
    const toastSelector = "text=/AI found \\d+ threats/i";
    try {
      // Wait for either threat cards or success toast
      await Promise.race([
        page.waitForSelector(threatCardSelector, {
          state: "visible",
          timeout: 180_000,
        }),
        page.locator(toastSelector).waitFor({ timeout: 180_000 }),
      ]);
    } catch {
      // If specific selectors fail, wait for any card-like elements in the AI panel
      console.log(
        "  Waiting for any threat content to appear in the AI panel...",
      );
      await page.waitForTimeout(5000);
    }
    // Extra settle time for UI to fully render
    await page.waitForTimeout(2000);
    console.log("  AI analysis complete — capturing results");

    // Switch to the Threats tab to show the persisted AI-generated threats
    await tour.step(page, {
      caption:
        "When the background job finishes, the AI-generated threats are persisted on the model and surface in the **Threats** tab. Switch tabs to see the full list — every threat is tied to a specific component or data flow, tagged with its STRIDE category, and assigned a severity. These are real AI outputs from qwen3-coder-next analyzing the Online Checkout architecture through the full async pipeline.",
      action: async () => {
        await page
          .getByRole("tab", { name: /^threats$/i })
          .first()
          .click()
          .catch(() => {});
        await page.waitForTimeout(1200);
      },
      highlight: 'button[role="tab"]:has-text("Threats")',
      settleMs: 600,
    });

    // ── Step 7: Explain threat detail ────────────────────────────────────────
    await tour.step(page, {
      caption:
        "Each threat row shows the title, severity badge, STRIDE category, and the component it targets. Click any row to expand the full analysis — step-by-step attack vector, technology-specific mitigation with code samples, a realistic effectiveness score capped at 0.85, and residual risk. Threats here flow into the mitigation workflow (Tour 8) and link to compliance requirements (Tour 7).",
      settleMs: 300,
    });

    // ── Step 8: Methodology + next steps ─────────────────────────────────────
    await tour.step(page, {
      caption:
        "The methodology dropdown lets you switch to **PASTA**, **Kill Chain**, or **MITRE ATT&CK** and re-analyze the same architecture — each surfaces complementary threats. For any accepted threat, **Generate Attack Tree** produces a hierarchical breakdown of how an attacker would progress. This AI analysis is real output from qwen3-coder-next via LM Studio — specific to the Online Checkout architecture, not boilerplate. Tour 4 shows a different starting point: letting the AI build the diagram itself from an uploaded SRS document.",
      settleMs: 300,
    });

    await tour.finalize();
  });
});
